<template><section class="battle-side-slots" :style="{left:`${38+position*383}px`}" :aria-label="`${label} 보드 슬롯`"><template v-if="mode==='speed'"><div class="side-slot speed-slot" aria-label="스피드 단계"><b>ϟ</b><small>{{ stage }}/8</small></div><div class="side-slot speed-slot"><b>{{ multiplier.toFixed(1) }}</b><small>배속</small></div><div class="side-slot speed-slot"><b>{{ Math.ceil(nextSpeed/1000) }}</b><small>초 후 가속</small></div></template><template v-else-if="itemStyle==='boosts'"><div v-for="(boost,index) in boostTypes" :key="boost.id" class="side-slot auto-slot" :class="{inactive:!boostState.selected.includes(boost.id)}" :aria-label="`${label} ${boost.name} ${boostState.selected.includes(boost.id)?'자동 적용':'꺼짐'}`" :title="`${boost.name}: 경기 전에 선택한 자동 부스트`"><b>{{ boost.icon }}</b><small>{{ index===0?boostState.shieldLeft:index===1?boostState.rushLeft:'AUTO' }}</small></div></template><template v-else><button v-for="slot in [0,1,2]" :key="slot" class="side-slot manual-slot" :disabled="disabled||item.cooldown>0||!item.inventory[slot]" :aria-label="`${label} ${item.inventory[slot]?ITEMS[item.inventory[slot]!]!.name:'빈 슬롯'} ${keys[slot]}`" :title="item.inventory[slot]?ITEMS[item.inventory[slot]!]!.description:'아이템 블록이 든 줄을 지워 수집하세요'" @click="$emit('use',slot)"><b>{{ item.inventory[slot]?ITEMS[item.inventory[slot]!]!.icon:'?' }}</b><small>{{ item.cooldown>0?`${Math.ceil(item.cooldown/1000)}s`:keys[slot] }}</small></button></template></section></template>
<script setup lang="ts">
import {ITEMS,type ItemState,type BoostState} from '~/game/GameModes'
const boostTypes=[{id:'shield' as const,name:'방패',icon:'⬡'},{id:'finalRush' as const,name:'Final Rush',icon:'⇧'},{id:'twinBomb' as const,name:'Twin Bomb',icon:'☢'}]
defineProps<{position:number;label:string;mode:string;itemStyle:'boosts'|'collect';boostState:BoostState;item:ItemState;disabled:boolean;keys:string[];stage:number;multiplier:number;nextSpeed:number}>()
defineEmits<{use:[slot:number]}>()
</script>
<style scoped>
.battle-side-slots{position:absolute;top:410px;width:48px;display:grid;gap:3px;z-index:4}.side-slot{position:relative;box-sizing:border-box;width:46px;height:26px;border:2px solid #5a5d5e;border-radius:5px;background:linear-gradient(#555,#222);box-shadow:inset 0 0 0 2px #121212,0 0 0 2px #080b09;display:flex;align-items:center;justify-content:center;gap:3px;color:#fff;font-family:Arial,sans-serif}.side-slot b{font-size:20px;line-height:1;font-weight:900;text-shadow:1px 2px #000}.side-slot small{font-size:7px;max-width:20px;line-height:1.2;color:#fff5ae}.auto-slot:first-child b{color:#b5e1fa}.auto-slot:nth-child(2) b{color:#ff9c39}.auto-slot:nth-child(3) b{color:#f7e438}.side-slot.inactive{opacity:.45;filter:grayscale(1)}.manual-slot{cursor:pointer;padding:1px}.manual-slot:disabled{cursor:default;opacity:.65}.manual-slot:focus-visible{outline:3px solid #ffdf24;outline-offset:3px}.manual-slot:active:not(:disabled){background:#558929}.speed-slot b{color:#ffe350;font-size:17px}.speed-slot small{font-size:6px}
</style>
